var plan = new SubscriptionPlan("Professional")
{
    MonthlyPrice = 29m,
    Features = ["Reports", "Exports"]
};

SubscriptionPlan annual = plan with { MonthlyPrice = 290m };
Console.WriteLine($"{annual.Name}: {annual.MonthlyPrice:C}");
Console.WriteLine(string.Join(", ", annual.Features));

public sealed record SubscriptionPlan(string Name)
{
    public required decimal MonthlyPrice { get; init; }
    public IReadOnlyList<string> Features { get; init; } = [];
}
